const { MaxPriorityQueue } = require("@datastructures-js/priority-queue");
const input = require("fs").readFileSync(0, "utf8");

function lastStoneWeight(stones) {
  const heap = MaxPriorityQueue.fromArray(stones);
  while (heap.size() > 1) {
    const first = heap.dequeue();
    const second = heap.dequeue();
    if (first !== second) {
      heap.enqueue(first - second);
    }
  }
  return heap.isEmpty() ? 0 : heap.front();
}

const [n, ...stones] = input.trim().split(/\s+/).map(Number);
console.log(lastStoneWeight(stones.slice(0, n)));

