#include <iostream>
#include <queue>
#include <vector>

int lastStoneWeight(const std::vector<int>& stones) {
    std::priority_queue<int> heap(stones.begin(), stones.end());
    while (heap.size() > 1) {
        int first = heap.top();
        heap.pop();
        int second = heap.top();
        heap.pop();
        if (first != second) {
            heap.push(first - second);
        }
    }
    return heap.empty() ? 0 : heap.top();
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> stones(n);
    for (int i = 0; i < n; i++) {
        std::cin >> stones[i];
    }
    std::cout << lastStoneWeight(stones) << "\n";
    return 0;
}

