package main

import (
	"container/heap"
	"fmt"
)

// maxHeap implements heap.Interface with the biggest number on top.
type maxHeap []int

func (h maxHeap) Len() int            { return len(h) }
func (h maxHeap) Less(i, j int) bool  { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *maxHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func lastStoneWeight(stones []int) int {
	h := maxHeap(stones)
	heap.Init(&h)
	for h.Len() > 1 {
		first := heap.Pop(&h).(int)
		second := heap.Pop(&h).(int)
		if first != second {
			heap.Push(&h, first-second)
		}
	}
	if h.Len() == 0 {
		return 0
	}
	return h[0]
}

func main() {
	var n int
	fmt.Scan(&n)
	stones := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&stones[i])
	}
	fmt.Println(lastStoneWeight(stones))
}

